#ifndef CS2_CLIENT_MOVEMENT_H
#define CS2_CLIENT_MOVEMENT_H

#include "viewmatrix.h"
#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>

namespace cs2::client {

// Standard Source 2 button bitmasks
enum MoveButtonBits : uint64_t {
    IN_ATTACK       = (1ULL << 0),
    IN_JUMP         = (1ULL << 1),
    IN_DUCK         = (1ULL << 2),
    IN_FORWARD      = (1ULL << 3),
    IN_BACK         = (1ULL << 4),
    IN_USE          = (1ULL << 5),
    IN_CANCEL       = (1ULL << 6),
    IN_LEFT         = (1ULL << 7),
    IN_RIGHT        = (1ULL << 8),
    IN_MOVELEFT     = (1ULL << 9),
    IN_MOVERIGHT    = (1ULL << 10),
    IN_ATTACK2      = (1ULL << 11),
    IN_RUN          = (1ULL << 12),
    IN_RELOAD       = (1ULL << 13),
    IN_ALT1         = (1ULL << 14),
    IN_ALT2         = (1ULL << 15),
    IN_SPEED        = (1ULL << 16),
    IN_WALK         = (1ULL << 17),
    IN_ZOOM         = (1ULL << 19),
    IN_BULLRUSH     = (1ULL << 22),
    IN_GRENADE1     = (1ULL << 23),
    IN_GRENADE2     = (1ULL << 24),
    IN_ATTACK3      = (1ULL << 25),
};

enum MoveType_t : uint8_t {
    MOVETYPE_NONE           = 0,
    MOVETYPE_ISOMETRIC      = 1,
    MOVETYPE_WALK           = 2,
    MOVETYPE_STEP           = 3,
    MOVETYPE_FLY            = 4,
    MOVETYPE_FLYGRAVITY     = 5,
    MOVETYPE_VPHYSICS       = 6,
    MOVETYPE_PUSH           = 7,
    MOVETYPE_NOCLIP         = 8,
    MOVETYPE_LADDER         = 9,
    MOVETYPE_OBSERVER       = 10,
    MOVETYPE_CUSTOM         = 11,
};

// Sub-tick input action event from CSGOUserCmdPB / CSubtickMoveStep
struct SubtickInputStep {
    float when = 0.0f;       // Sub-tick fractional offset [0.0, 1.0]
    uint64_t button = 0;     // MoveButtonBits
    bool pressed = false;    // True if key-down, false if key-up
};

// Movement simulation trace / collision result
struct MoveTrace_t {
    Vector3 startPos;
    Vector3 endPos;
    Vector3 planeNormal;
    float fraction = 1.0f;
    bool allSolid = false;
    bool startSolid = false;
    uint32_t hitEntityHandle = 0xFFFFFFFF;
};

// Player movement parameters passed into ProcessMovement (matching CMoveData)
struct PlayerMoveData {
    uint32_t playerHandle = 0xFFFFFFFF;
    MoveType_t moveType = MOVETYPE_WALK;
    Vector3 origin;
    Vector3 velocity;
    Vector3 baseVelocity;
    Vector3 viewAngles;
    Vector3 wishVelocity;
    Vector3 wishDirection;
    float wishSpeed = 0.0f;
    float forwardMove = 0.0f;
    float sideMove = 0.0f;
    float upMove = 0.0f;
