        posWriter.WriteTag(1, WireType::Fixed32);
        posWriter.WriteFloat(shoot_position.x);
        posWriter.WriteTag(2, WireType::Fixed32);
        posWriter.WriteFloat(shoot_position.y);
        posWriter.WriteTag(3, WireType::Fixed32);
