constexpr uint32_t FCVAR_NOTIFY             = (1 << 8);
constexpr uint32_t FCVAR_REPLICATED         = (1 << 13); // Bit 13 / 0x2000: Server authoritative
constexpr uint32_t FCVAR_CHEAT              = (1 << 14); // Bit 14 / 0x4000: Protected by sv_cheats

